"use client"

/**
 * niko-table — created by Semir N. (Semkoo, https://github.com/Semkoo) with AI assistance.
 *
 * Before reporting anything: please check the changelog first.
 *  - In-repo: ./CHANGELOG.md
 *  - Docs site: https://niko-table.com/changelog
 *
 * Found a bug or have a fix? Open an issue or PR on GitHub so other
 * users (and future LLMs reading this code) benefit:
 * https://github.com/Semkoo/niko-table-registry
 */

/**
 * A dropdown menu component that allows users to toggle the visibility of table columns.
 * It uses a popover to display a list of columns with checkboxes.
 *
 * Two opt-in extensions:
 *   - `lockedColumnIds`: include columns marked `enableHiding: false` in the
 *     list, but render them disabled (always-on, can't toggle).
 *   - `onReset` + `resetLabel`: render a Reset button below a separator.
 *
 * Tuned for large column counts (200+): rows are a memoized component, the
 * search filter runs at this layer (so non-matching rows skip rendering
 * entirely), and `lockedColumnIds` is consulted via a `Set` for O(1) lookups.
 *
 * For drag-to-reorder, see `TableViewDndMenu` — it lives in a separate file
 * so consumers who don't need DnD don't pay the `@dnd-kit/*` bundle cost.
 */

import type { RowData } from "@tanstack/react-table"
import { Check, ChevronsUpDown, RotateCcw, Settings2 } from "lucide-react"
import * as React from "react"
import { Button } from "@/components/niko-table/primitives/button"
import {
  Command,
  CommandEmpty,
  CommandGroup,
  CommandInput,
  CommandItem,
  CommandList,
} from "@/components/niko-table/primitives/command"
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/niko-table/primitives/popover"
import { cn } from "@/lib/utils"
import { formatLabel } from "../lib/format"

import type { DataTableColumn, DataTableInstance } from "../types"
function getColumnTitle<TData extends RowData>(
  column: DataTableColumn<TData, unknown>,
): string {
  return column.columnDef.meta?.label ?? formatLabel(column.id)
}

export interface TableViewMenuProps<TData extends RowData> {
  table: DataTableInstance<TData>
  className?: string
  onColumnVisibilityChange?: (columnId: string, isVisible: boolean) => void
  /**
   * Column ids that should appear in the menu but cannot be toggled off.
   * Useful for columns the table marks `enableHiding: false` but the
   * consumer still wants visible in the column list (typically with a
   * Reset to Defaults affordance below).
   */
  lockedColumnIds?: string[]
  /**
   * When provided, renders a Reset button at the bottom of the menu.
   * Useful when paired with persisted column preferences so users can
   * revert to defaults.
   */
  onReset?: () => void
  /** Label for the reset button. Defaults to "Reset to defaults". */
  resetLabel?: string
  /**
   * Replaces the default toolbar button.
   *
   * Same `trigger` contract the sibling filters already expose
   * (`TableColumnActions`, `TableDateFilter`, `TableFacetedFilter`), so a
   * consumer that needs a different trigger shape — a header-sized bare icon
   * beside a column title, for instance — composes one instead of waiting for
   * a boolean per shape.
   */
  trigger?: React.ReactNode
}

interface MenuRowProps<TData extends RowData> {
  column: DataTableColumn<TData, unknown>
  isLocked: boolean
  isVisible: boolean
  onToggle: (columnId: string) => void
}

const MenuRow = React.memo(function MenuRow<TData extends RowData>({
  column,
  isLocked,
  isVisible,
  onToggle,
}: MenuRowProps<TData>) {
  return (
    <CommandItem
      data-disabled={isLocked ? "" : undefined}
      onSelect={() => {
        if (isLocked) return
        onToggle(column.id)
      }}
    >
      <span className={cn("truncate", isLocked && "text-muted-foreground")}>
        {getColumnTitle(column)}
      </span>
      <Check
        className={cn(
          "ml-auto size-4 shrink-0",
          isLocked ? "opacity-50" : isVisible ? "opacity-100" : "opacity-0",
        )}
      />
    </CommandItem>
  )
}) as <TData extends RowData>(props: MenuRowProps<TData>) => React.ReactElement

export function TableViewMenu<TData extends RowData>({
  table,
  onColumnVisibilityChange,
  lockedColumnIds,
  onReset,

  trigger,
  resetLabel,
}: TableViewMenuProps<TData>) {
  // Controlled search. cmdk's built-in filter hides non-matching `CommandItem`s
  // but still renders all of them — at 200+ columns that's the bottleneck.
  // Filtering at this layer means non-matching rows skip rendering entirely.
  const [search, setSearch] = React.useState("")

  // O(1) lookups instead of O(m) `.includes()` per row.
  const lockedSet = React.useMemo(
    () => new Set(lockedColumnIds ?? []),
    [lockedColumnIds],
  )

  const columns = React.useMemo(
    () =>
      table
        .getAllColumns()
        .filter(
          column =>
            typeof column.accessorFn !== "undefined" &&
            (column.getCanHide() || lockedSet.has(column.id)),
        ),
    // Depend on the column set, not just the (stable) table ref.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [table, table.options.columns, lockedSet],
  )

  const visibleColumns = React.useMemo(() => {
    const q = search.trim().toLowerCase()
    if (!q) return columns
    return columns.filter(c => getColumnTitle(c).toLowerCase().includes(q))
  }, [columns, search])

  // Stable callback so memoized rows skip re-render on keystrokes.
  const onToggle = React.useCallback(
    (columnId: string) => {
      const column = table.getColumn(columnId)
      if (!column) return
      const newVisibility = !column.getIsVisible()
      column.toggleVisibility(newVisibility)
      onColumnVisibilityChange?.(columnId, newVisibility)
    },
    [table, onColumnVisibilityChange],
  )

  return (
    <Popover>
      <PopoverTrigger asChild>
        {trigger ?? (
          <Button
            aria-label="Toggle columns"
            role="combobox"
            variant="outline"
            size="sm"
            className="ml-auto hidden h-8 lg:flex"
          >
            <Settings2 />
            View
            <ChevronsUpDown className="ml-auto opacity-50" />
          </Button>
        )}
      </PopoverTrigger>
      <PopoverContent align="end" className="w-fit p-0">
        <Command shouldFilter={false}>
          <CommandInput
            placeholder="Search columns..."
            value={search}
            onValueChange={setSearch}
          />
          <CommandList>
            <CommandEmpty>No columns found.</CommandEmpty>
            <CommandGroup>
              {visibleColumns.map(column => (
                <MenuRow
                  key={column.id}
                  column={column}
                  isLocked={lockedSet.has(column.id)}
                  isVisible={column.getIsVisible()}
                  onToggle={onToggle}
                />
              ))}
            </CommandGroup>
          </CommandList>
          {onReset ? (
            <>
              <div className="border-t" />
              <Button
                variant="ghost"
                size="sm"
                className="w-full justify-start gap-2 rounded-none text-muted-foreground"
                onClick={onReset}
              >
                <RotateCcw className="size-4" />
                {resetLabel ?? "Reset to defaults"}
              </Button>
            </>
          ) : null}
        </Command>
      </PopoverContent>
    </Popover>
  )
}

/**
 * @required displayName is required for auto feature detection
 * @see "feature-detection.ts"
 */

TableViewMenu.displayName = "TableViewMenu"

"use client"

/**
 * Niko Table's popover primitive, React Aria build. Radix-shaped API
 * (`Popover open onOpenChange`, `PopoverTrigger asChild`, `PopoverContent
 * align side sideOffset`) on top of `react-aria-components` `Pressable` and the
 * React Aria shadcn `Popover` (a modal React Aria popover anchored to the
 * trigger through `triggerRef`).
 */
import * as React from "react"
import { mergeProps } from "react-aria"
import { Pressable, type Placement } from "react-aria-components"

import { Popover as PopoverPrimitive } from "@/components/ui/popover"

type Side = "top" | "right" | "bottom" | "left"
type Align = "start" | "center" | "end"
type PressableChild = React.ComponentProps<typeof Pressable>["children"]

function toPlacement(side: Side, align: Align): Placement {
  if (align === "center") return side
  if (side === "top" || side === "bottom") return `${side} ${align}`
  return `${side} ${align === "start" ? "top" : "bottom"}`
}

interface PopoverContextValue {
  open: boolean
  setOpen: (open: boolean) => void
  triggerRef: React.RefObject<HTMLElement | null>
}

const PopoverContext = React.createContext<PopoverContextValue | null>(null)

function usePopover(part: string) {
  const context = React.useContext(PopoverContext)
  if (!context) throw new Error(`${part} must be used within <Popover>`)
  return context
}

function Popover({
  open: openProp,
  defaultOpen = false,
  onOpenChange,
  children,
}: {
  open?: boolean
  defaultOpen?: boolean
  onOpenChange?: (open: boolean) => void
  /** Radix option; React Aria popovers are always modal. */
  modal?: boolean
  children?: React.ReactNode
}) {
  const [uncontrolledOpen, setUncontrolledOpen] = React.useState(defaultOpen)
  const open = openProp ?? uncontrolledOpen
  const triggerRef = React.useRef<HTMLElement>(null)
  const setOpen = React.useCallback(
    (next: boolean) => {
      if (openProp === undefined) setUncontrolledOpen(next)
      onOpenChange?.(next)
    },
    [openProp, onOpenChange],
  )
  const value = React.useMemo(
    () => ({ open, setOpen, triggerRef }),
    [open, setOpen],
  )
  return (
    <PopoverContext.Provider value={value}>{children}</PopoverContext.Provider>
  )
}

function PopoverTrigger({
  asChild = false,
  children,
  ...props
}: React.ComponentProps<"button"> & { asChild?: boolean }) {
  const { open, setOpen, triggerRef } = usePopover("PopoverTrigger")
  const state = {
    "aria-expanded": open,
    "aria-haspopup": "dialog" as const,
    "data-state": open ? "open" : "closed",
  }
  const child =
    asChild &&
    React.isValidElement<React.HTMLAttributes<HTMLElement>>(children) ? (
      // Slot: the trigger's own props (refs, handlers, classes) merge onto the child.
      React.cloneElement(
        children,
        mergeProps(
          children.props,
          props,
          state,
        ) as React.HTMLAttributes<HTMLElement>,
      )
    ) : (
      <button type="button" {...props} {...state}>
        {children}
      </button>
    )
  return (
    <Pressable ref={triggerRef} onPress={() => setOpen(!open)}>
      {/* Pressable types its child as a host element; ours forward ref + props. */}
      {child as PressableChild}
    </Pressable>
  )
}

function PopoverContent({
  align = "center",
  side = "bottom",
  sideOffset = 4,
  alignOffset = 0,
  id,
  className,
  children,
  ...props
}: Omit<
  React.ComponentProps<typeof PopoverPrimitive>,
  | "children"
  | "className"
  | "placement"
  | "offset"
  | "crossOffset"
  | "isOpen"
  | "onOpenChange"
  | "triggerRef"
> & {
  align?: Align
  side?: Side
  sideOffset?: number
  alignOffset?: number
  /** Radix puts it on the popup; React Aria's popover takes no `id`. */
  id?: string
  className?: string
  children?: React.ReactNode
}) {
  const { open, setOpen, triggerRef } = usePopover("PopoverContent")
  return (
    <PopoverPrimitive
      {...props}
      triggerRef={triggerRef}
      isOpen={open}
      onOpenChange={setOpen}
      placement={toPlacement(side, align)}
      offset={sideOffset}
      crossOffset={alignOffset}
      className={className}
      data-state={open ? "open" : "closed"}
    >
      {id ? (
        <div id={id} className="contents">
          {children}
        </div>
      ) : (
        children
      )}
    </PopoverPrimitive>
  )
}

export { Popover, PopoverContent, PopoverTrigger }

"use client"

/**
 * Niko Table's button primitive, React Aria build. Same API as the shadcn
 * Radix `Button` (native `<button>` props, `variant`, `size`, `asChild`), styled
 * with the React Aria shadcn `buttonVariants`. A native button (not the React
 * Aria `Button`) keeps `onClick` / `disabled` / `type` / `ref` working at every
 * Niko Table call site, and lets the overlay triggers wrap it in `Pressable`.
 */
import * as React from "react"
import { mergeProps } from "react-aria"
import type { VariantProps } from "class-variance-authority"

import { buttonVariants } from "@/components/ui/button"
import { cn } from "@/lib/utils"

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  children,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    asChild?: boolean
  }) {
  const classes = cn(buttonVariants({ variant, size }), className)

  if (
    asChild &&
    React.isValidElement<React.HTMLAttributes<HTMLElement>>(children)
  ) {
    // Slot: the child element is the button (e.g. a link styled as one); its
    // own handlers and refs compose with the button's.
    return React.cloneElement(children, {
      ...mergeProps(children.props, { "data-slot": "button" }, props),
      className: cn(classes, children.props.className),
    } as React.HTMLAttributes<HTMLElement>)
  }

  return (
    <button
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={classes}
      {...props}
    >
      {children}
    </button>
  )
}

export { Button }

"use client"

/**
 * Niko Table's command primitive, React Aria build. Niko Table relies on cmdk
 * semantics (free-form children, `CommandEmpty`, a controlled search value,
 * value-based `onSelect`, `shouldFilter`), which the React Aria shadcn
 * `command` (an `Autocomplete` over a `Menu` collection) does not offer. This
 * build keeps cmdk (headless; it bundles a few Radix packages internally)
 * under the same names, styled like the other shadcn lists. Requires the
 * `cmdk` npm package; it does not use `@/components/ui/command`.
 */
import * as React from "react"
import { Command as CommandPrimitive } from "cmdk"
import { SearchIcon } from "lucide-react"

import { cn } from "@/lib/utils"

function Command({
  className,
  ...props
}: React.ComponentProps<typeof CommandPrimitive>) {
  return (
    <CommandPrimitive
      data-slot="command"
      className={cn(
        "flex h-full w-full flex-col overflow-hidden rounded-md bg-popover text-popover-foreground",
        className,
      )}
      {...props}
    />
  )
}

function CommandInput({
  className,
  ...props
}: React.ComponentProps<typeof CommandPrimitive.Input>) {
  return (
    <div
      data-slot="command-input-wrapper"
      className="flex h-9 items-center gap-2 border-b px-3"
    >
      <SearchIcon className="size-4 shrink-0 opacity-50" />
      <CommandPrimitive.Input
        data-slot="command-input"
        className={cn(
          "flex h-10 w-full rounded-md bg-transparent py-3 text-sm outline-hidden placeholder:text-muted-foreground disabled:cursor-not-allowed disabled:opacity-50",
          className,
        )}
        {...props}
      />
    </div>
  )
}

function CommandList({
  className,
  ...props
}: React.ComponentProps<typeof CommandPrimitive.List>) {
  return (
    <CommandPrimitive.List
      data-slot="command-list"
      className={cn(
        "max-h-[300px] scroll-py-1 overflow-x-hidden overflow-y-auto",
        className,
      )}
      {...props}
    />
  )
}

function CommandEmpty({
  ...props
}: React.ComponentProps<typeof CommandPrimitive.Empty>) {
  return (
    <CommandPrimitive.Empty
      data-slot="command-empty"
      className="py-6 text-center text-sm"
      {...props}
    />
  )
}

function CommandGroup({
  className,
  ...props
}: React.ComponentProps<typeof CommandPrimitive.Group>) {
  return (
    <CommandPrimitive.Group
      data-slot="command-group"
      className={cn(
        "overflow-hidden p-1 text-foreground **:[[cmdk-group-heading]]:px-2 **:[[cmdk-group-heading]]:py-1.5 **:[[cmdk-group-heading]]:text-xs **:[[cmdk-group-heading]]:font-medium **:[[cmdk-group-heading]]:text-muted-foreground",
        className,
      )}
      {...props}
    />
  )
}

function CommandSeparator({
  className,
  ...props
}: React.ComponentProps<typeof CommandPrimitive.Separator>) {
  return (
    <CommandPrimitive.Separator
      data-slot="command-separator"
      className={cn("-mx-1 h-px bg-border", className)}
      {...props}
    />
  )
}

function CommandItem({
  className,
  ...props
}: React.ComponentProps<typeof CommandPrimitive.Item>) {
  return (
    <CommandPrimitive.Item
      data-slot="command-item"
      className={cn(
        "relative flex cursor-default items-center gap-2 rounded-sm px-2 py-1.5 text-sm outline-hidden select-none data-[disabled=true]:pointer-events-none data-[disabled=true]:opacity-50 data-[selected=true]:bg-accent data-[selected=true]:text-accent-foreground [&_svg]:pointer-events-none [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4 [&_svg:not([class*='text-'])]:text-muted-foreground",
        className,
      )}
      {...props}
    />
  )
}

export {
  Command,
  CommandInput,
  CommandList,
  CommandEmpty,
  CommandGroup,
  CommandItem,
  CommandSeparator,
}
